import { logsClient } from "@dynatrace-sdk/client-classic-environment-v2";

export default async function (payload: unknown = undefined) {
  const accountId = 'b13b6aa8-0eb3-4e63-abdd-b2998414afd9';

  // Step 1: Get access token
  const tokenResponse = await fetch('https://sso.dynatrace.com/sso/oauth2/token', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded',
    },
    body: new URLSearchParams({
      grant_type: 'client_credentials',
      client_id: '<client_id>',
      client_secret: '<oauth Secret>',
      scope:
        'iam-policies-management iam:policies:write iam:policies:read iam:bindings:write iam:bindings:read iam:effective-permissions:read account-idm-read account-idm-write',
      resource: `urn:dtaccount:${accountId}`,
    }).toString(),
  });

  if (!tokenResponse.ok) {
    const err = await tokenResponse.text();
    throw new Error(`Token request failed: ${err}`);
  }

  const tokenData = await tokenResponse.json();
  const accessToken = tokenData.access_token;

  const headers = {
    Authorization: `Bearer ${accessToken}`,
    Accept: 'application/json',
  };

  // Step 2: Fetch all users
  const usersResponse = await fetch(
    `https://api.dynatrace.com/iam/v1/accounts/${accountId}/users?service-users=false`,
    { method: 'GET', headers }
  );

  if (!usersResponse.ok) {
    const err = await usersResponse.text();
    throw new Error(`Failed to fetch users: ${err}`);
  }

  const usersData = await usersResponse.json();
  const users = usersData.items || [];

  // Build a map of users by email for quick lookup
  const userMap: Record<string, any> = {};
  for (const user of users) {
    userMap[user.email] = {
      ...user,
      groups: [],
      "log.source": "alstom/audit/users"
    };
  }

  // Step 3: Fetch all groups
  const groupsResponse = await fetch(
    `https://api.dynatrace.com/iam/v1/accounts/${accountId}/groups`,
    { method: 'GET', headers }
  );

  if (!groupsResponse.ok) {
    const err = await groupsResponse.text();
    throw new Error(`Failed to fetch groups: ${err}`);
  }

  const groupsData = await groupsResponse.json();
  const groups = groupsData.items || [];

  // Step 4: For each group, fetch its users and update each user's group list
  for (const group of groups) {
    const groupId = group.uuid;
    const groupName = group.name;

    const groupUsersResponse = await fetch(
      `https://api.dynatrace.com/iam/v1/accounts/${accountId}/groups/${groupId}/users`,
      { method: 'GET', headers }
    );

    if (groupUsersResponse.ok) {
      const groupUsersData = await groupUsersResponse.json();
      const groupUserEmails = groupUsersData.items?.map((u: any) => u.email) || [];

      for (const email of groupUserEmails) {
        if (userMap[email]) {
          userMap[email].groups.push(groupName);
        }
      }
    }
  }

  // Step 5: Filter and return only selected fields

  const data = await logsClient.storeLog({
  type: "application/json",
  body: Object.values(userMap),
  });

return data;

}
